#include <iostream>
#include <bitset>

int main() {
    char letter = 'C';
    int asciiValue = static_cast<int>(letter);
    std::bitset<8> binaryRepresentation(static_cast<unsigned long long>(letter));

    std::cout << "Character: " << letter << "\n";
    std::cout << "ASCII Decimal: " << asciiValue << "\n";
    std::cout << "Binary (1 Byte): " << binaryRepresentation << "\n";
    std::cout << "Size of char: " << sizeof(letter) << " byte" << "\n";

    return 0;
}
